import termios, os, tty, pty
print(termios.TCSANOW, termios.TCSADRAIN, termios.TCSAFLUSH, termios.ICANON != 0, termios.ECHO != 0, termios.VMIN != termios.VTIME)
print(termios.error.__module__, issubclass(termios.error, Exception))
r, w = os.pipe()
try: termios.tcgetattr(r)
except termios.error as e: print(type(e).__name__, e.args[0] in (25, 19), e.args[1])
try: termios.tcgetattr(1000)
except termios.error as e: print(e.args[0])
m, s = os.openpty()
a = termios.tcgetattr(s)
print(len(a), len(a[6]) == termios.NCCS, type(a[6][0]), isinstance(a[4], int), a[3] & termios.ICANON != 0)
saved = list(a)
tty.setraw(s)
b = termios.tcgetattr(s)
print(b[3] & (termios.ICANON | termios.ECHO), type(b[6][termios.VMIN]), b[6][termios.VMIN], b[6][termios.VTIME])
termios.tcsetattr(s, termios.TCSANOW, saved)
c = termios.tcgetattr(s)
print(c[6] == saved[6])
tty.setcbreak(s)
d = termios.tcgetattr(s)
print(d[3] & termios.ICANON, d[3] & termios.ECHO)
termios.tcsetattr(s, termios.TCSAFLUSH, saved)
termios.tcsetwinsize(s, (24, 80))
print(termios.tcgetwinsize(s))
termios.tcflush(s, termios.TCIOFLUSH)
print(tty.isatty(s) if hasattr(tty, 'isatty') else os.isatty(s))
for f in (lambda: termios.tcsetattr(s, termios.TCSANOW, [1]), lambda: termios.tcgetattr("x"), lambda: termios.tcsetwinsize(s, 5)):
    try: f()
    except Exception as e: print(type(e).__name__)
os.close(m); os.close(s)
print(tty.CC, tty.LFLAG, tty.__all__)
